import { useMemo, useState, type ComponentType } from 'react'
import { ArrowRight, CheckCircle2, CircleAlert, FileSearch, GitCompare, ShieldCheck, Target } from 'lucide-react'

type ComplianceIcon = ComponentType<{ className?: string }>

export type ComplianceIntelligenceItem = { id: string; framework: string; control: string; status: 'pass' | 'fail' | 'partial' | 'not_assessed'; findingCount?: number; evidenceCount?: number; validationCount?: number; impact?: number }

export function ComplianceIntelligence({ items }: { items: ComplianceIntelligenceItem[] }) {
  const [selectedId, setSelectedId] = useState(items[0]?.id ?? null)
  const selected = items.find((item) => item.id === selectedId)
  const summary = useMemo(() => ({ pass: items.filter((i) => i.status === 'pass').length, fail: items.filter((i) => i.status === 'fail').length, partial: items.filter((i) => i.status === 'partial').length, assessed: items.filter((i) => i.status !== 'not_assessed').length }), [items])
  if (!items.length) return <section className="rounded-2xl border bg-card p-8 text-center"><ShieldCheck className="mx-auto h-8 w-8 text-muted-foreground" /><h3 className="mt-3 text-sm font-semibold">No compliance controls assessed</h3><p className="mt-1 text-xs text-muted-foreground">Run a validation with compliance mapping enabled to build evidence-backed coverage.</p></section>
  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="border-b px-5 py-4"><div className="flex items-center gap-2 font-semibold"><ShieldCheck className="h-4 w-4 text-primary" /> Compliance Intelligence</div><p className="mt-1 text-xs text-muted-foreground">Control → Finding → Evidence → Validation → Executive impact.</p></header><div className="grid grid-cols-2 gap-px border-b bg-border md:grid-cols-4">{[['Passed', summary.pass], ['Failed', summary.fail], ['Partial', summary.partial], ['Assessed', summary.assessed]].map(([label, value]) => <div key={String(label)} className="bg-card p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-2xl font-black">{value}</div></div>)}</div><div className="grid lg:grid-cols-[minmax(0,1fr)_360px]"><div className="divide-y">{items.map((item) => <button key={item.id} type="button" onClick={() => setSelectedId(item.id)} className={`flex w-full items-center gap-3 px-5 py-4 text-left transition hover:bg-muted/30 ${item.id === selectedId ? 'bg-primary/5' : ''}`} aria-pressed={item.id === selectedId}><span className="grid h-9 w-9 place-items-center rounded-lg border bg-background">{item.status === 'pass' ? <CheckCircle2 className="h-4 w-4 text-emerald-600" /> : item.status === 'fail' ? <CircleAlert className="h-4 w-4 text-destructive" /> : <Target className="h-4 w-4 text-amber-600" />}</span><span className="min-w-0 flex-1"><span className="block text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{item.framework}</span><span className="mt-0.5 block truncate text-xs font-semibold">{item.control}</span></span><span className="text-[10px] font-bold uppercase text-muted-foreground">{item.status.replace('_', ' ')}</span></button>)}</div><aside className="border-t bg-muted/10 p-5 lg:border-l lg:border-t-0"><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Control intelligence</div>{selected && <><h3 className="mt-2 font-semibold">{selected.control}</h3><div className="mt-1 text-xs text-muted-foreground">{selected.framework}</div><div className="mt-5 space-y-2">{([['Findings', selected.findingCount ?? 0, CircleAlert], ['Evidence', selected.evidenceCount ?? 0, FileSearch], ['Validations', selected.validationCount ?? 0, GitCompare]] as [string, number, ComplianceIcon][]).map(([label, value, Icon]) => <div key={String(label)} className="flex items-center justify-between rounded-lg border bg-background px-3 py-2"><span className="flex items-center gap-2 text-xs"><Icon className="h-3.5 w-3.5" />{label}</span><span className="text-xs font-bold">{value}</span></div>)}<div className="mt-4 rounded-xl border p-3"><div className="flex items-center gap-2 text-[10px] font-semibold uppercase tracking-wider"><ArrowRight className="h-3 w-3" /> Executive impact</div><div className="mt-1 text-sm font-semibold">{selected.impact !== undefined ? `${Math.round(selected.impact)}/100` : 'Not assessed'}</div></div></div></>}</aside></div></section>
}
